// Normalize the HubSpot webhook payload into the shape the rest of the flow expects.
const body = $json.body || $json;
const contact = body.contact || body;

const email = (contact.email || contact.properties?.email || '').toLowerCase().trim();
const domain = email.split('@')[1] || '';

const freeMailDomains = new Set([
  'gmail.com', 'yahoo.com', 'outlook.com', 'hotmail.com',
  'icloud.com', 'aol.com', 'proton.me', 'protonmail.com'
]);

return [{
  json: {
    contactId: String(contact.id || contact.contactId || body.contactId || ''),
    email,
    domain,
    isFreeMail: freeMailDomains.has(domain),
    firstName: contact.properties?.firstname || contact.firstName || '',
    lastName: contact.properties?.lastname || contact.lastName || '',
    companyHint: contact.properties?.company || contact.company || '',
    jobTitle: contact.properties?.jobtitle || contact.jobTitle || '',
    formId: body.formId || body.form?.id || '',
    formResponses: body.form_responses || body.formResponses || contact.properties?.message || '',
    submittedAt: body.submittedAt || new Date().toISOString(),
  }
}];

// Combine normalized payload + enrichment into a single bundle for Claude.
const lead = $('Normalize Payload').item.json;
const enrich = $json?.organization || {};

return [{
  json: {
    ...lead,
    company: enrich.name || lead.companyHint || lead.domain,
    industry: enrich.industry || '',
    employeeCount: enrich.estimated_num_employees || enrich.employee_count || null,
    annualRevenue: enrich.annual_revenue || null,
    country: enrich.country || '',
    state: enrich.state || '',
    technologies: Array.isArray(enrich.technologies) ? enrich.technologies.slice(0, 12) : [],
    enrichmentOk: !!enrich.name,
  }
}];

