parameters.jsCode:
// Parse Claude's JSON. If anything fails (timeout, malformed, free-mail cap), fall back to a rule-based score.
const lead = $('Merge Lead + Firmographics').item.json;
const raw = $json?.content?.[0]?.text || '';

let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = null;
}

function ruleBasedScore(l) {
  let s = 5;
  if (l.isFreeMail) s -= 2;
  if (!l.enrichmentOk) s -= 1;
  const ec = l.employeeCount || 0;
  if (ec >= 200 && ec <= 5000) s += 2;
  else if (ec >= 50 && ec < 200) s += 1;
  else if (ec >= 5000) s += 1;
  if ((l.jobTitle || '').match(/director|vp|head|chief|cro|cmo|ceo/i)) s += 1;
  return Math.max(1, Math.min(10, s));
}

const usedFallback = !parsed || typeof parsed.score !== 'number';
const score = usedFallback ? ruleBasedScore(lead) : Math.max(1, Math.min(10, parsed.score));
const capped = lead.isFreeMail && score > 4 ? 4 : score;

return [{
  json: {
    ...lead,
    score: capped,
    reasoning: parsed?.reasoning || (usedFallback ? 'Rule-based fallback (Claude unavailable or malformed).' : ''),
    primary_pain_hypothesis: parsed?.primary_pain_hypothesis || '',
    disqualifiers: parsed?.disqualifiers || (lead.isFreeMail ? ['free-mail-domain'] : []),
    scoringMethod: usedFallback ? 'rule-based' : 'claude',
  }
}];

